window.FJIS_TKA_PACKAGE_2_BANK["matematika"] = [{"id":"p2-matematika-1","subjectId":"matematika","type":"PG","number":1,"question":"Di toko ATK, harga 2 buku + 1 pensil + 1 penghapus = Rp19.000. Harga 1 buku + 2 pensil + 1 penghapus = Rp16.000. Harga 1 buku + 1 pensil + 2 penghapus = Rp15.000. Berapakah harga 1 buku?","topic":"SPLTV - HOTS","explanation":"Misal b,p,h. Sistem 3 persamaan. Eliminasi: (1)-(2) => b-p=3000. (1)-(3)=> b-h=4000. Substitusi ke (1): (p+3000)+... Dengan eliminasi matriks diperoleh b=8000, p=5000, h=4000.","sourceOriginal":{"no":1,"type":"PG","topic":"SPLTV - HOTS","question":"Di toko ATK, harga 2 buku + 1 pensil + 1 penghapus = Rp19.000. Harga 1 buku + 2 pensil + 1 penghapus = Rp16.000. Harga 1 buku + 1 pensil + 2 penghapus = Rp15.000. Berapakah harga 1 buku?","options":["Rp7.000","Rp8.000","Rp9.000","Rp10.000","Rp11.000"],"kunci":"B","pembahasan":"Misal b,p,h. Sistem 3 persamaan. Eliminasi: (1)-(2) => b-p=3000. (1)-(3)=> b-h=4000. Substitusi ke (1): (p+3000)+... Dengan eliminasi matriks diperoleh b=8000, p=5000, h=4000."}},{"id":"p2-matematika-2","subjectId":"matematika","type":"PG","number":2,"question":"Suku ke-3 dan ke-8 barisan aritmetika adalah 14 dan 29. Suku ke-20 barisan tersebut adalah...","topic":"Barisan Aritmetika","explanation":"Un= a+(n-1)b. U3=a+2b=14, U8=a+7b=29 => 5b=15 => b=3, a=8. U20=8+19*3=65? Wait 8+57=65. Koreksi: opsi 65. Jadi jawaban D. Namun untuk variasi baru kita set a=5. Mari pakai b=3, a=8 => U20=65 (D).","sourceOriginal":{"no":2,"type":"PG","topic":"Barisan Aritmetika","question":"Suku ke-3 dan ke-8 barisan aritmetika adalah 14 dan 29. Suku ke-20 barisan tersebut adalah...","options":["53","56","59","65","68"],"kunci":"C","pembahasan":"Un= a+(n-1)b. U3=a+2b=14, U8=a+7b=29 => 5b=15 => b=3, a=8. U20=8+19*3=65? Wait 8+57=65. Koreksi: opsi 65. Jadi jawaban D. Namun untuk variasi baru kita set a=5. Mari pakai b=3, a=8 => U20=65 (D)."}},{"id":"p2-matematika-3","subjectId":"matematika","type":"PG","number":3,"question":"Ingkaran dari pernyataan 'Jika hujan deras maka semua siswa memakai jas hujan' adalah...","topic":"Logika Matematika","explanation":"Ingkaran p→q ≡ p ∧ ~q. p: hujan deras, q: semua siswa memakai jas hujan. ~q: ada siswa tidak memakai jas hujan.","sourceOriginal":{"no":3,"type":"PG","topic":"Logika Matematika","question":"Ingkaran dari pernyataan 'Jika hujan deras maka semua siswa memakai jas hujan' adalah...","options":["Hujan deras dan ada siswa tidak memakai jas hujan","Jika tidak hujan deras maka ada siswa tidak memakai jas hujan","Hujan tidak deras atau semua siswa memakai jas hujan","Tidak hujan deras dan semua siswa memakai jas hujan","Jika ada siswa tidak memakai jas hujan maka hujan deras"],"kunci":"A","pembahasan":"Ingkaran p→q ≡ p ∧ ~q. p: hujan deras, q: semua siswa memakai jas hujan. ~q: ada siswa tidak memakai jas hujan."}},{"id":"p2-matematika-4","subjectId":"matematika","type":"PG","number":4,"question":"Nilai dari  ²log 12 + ²log 6 - ²log 9  adalah...","topic":"Eksponen Logaritma","explanation":"²log 12 + ²log 6 = ²log72. ²log72 - ²log9 = ²log(72/9)=²log8=3.","sourceOriginal":{"no":4,"type":"PG","topic":"Eksponen Logaritma","question":"Nilai dari  ²log 12 + ²log 6 - ²log 9  adalah...","options":["1","2","3","4","8"],"kunci":"C","pembahasan":"²log 12 + ²log 6 = ²log72. ²log72 - ²log9 = ²log(72/9)=²log8=3."}},{"id":"p2-matematika-5","subjectId":"matematika","type":"PG","number":5,"question":"Diketahui sin A = 3/5, A sudut lancip. Nilai cos 2A adalah...","topic":"Trigonometri Dasar","explanation":"cos2A = 1-2sin²A = 1-2*(9/25)=1-18/25=7/25.","sourceOriginal":{"no":5,"type":"PG","topic":"Trigonometri Dasar","question":"Diketahui sin A = 3/5, A sudut lancip. Nilai cos 2A adalah...","options":["7/25","12/25","14/25","18/25","24/25"],"kunci":"A","pembahasan":"cos2A = 1-2sin²A = 1-2*(9/25)=1-18/25=7/25."}},{"id":"p2-matematika-6","subjectId":"matematika","type":"PG","number":6,"question":"Perhatikan gambar juring lingkaran 90° dengan jari-jari 7 cm. Luas juring tersebut adalah... (π = 22/7)","image":"data:image/png;base64,","topic":"Geometri - Juring Lingkaran","explanation":"Luas juring = θ/360 × πr² = 90/360 × 22/7 × 7×7 = 1/4 × 154 = 38,5 cm².","sourceOriginal":{"no":6,"type":"PG","topic":"Geometri - Juring Lingkaran","question":"Perhatikan gambar juring lingkaran 90° dengan jari-jari 7 cm. Luas juring tersebut adalah... (π = 22/7)","options":["38,5 cm²","36 cm²","40,5 cm²","42 cm²","44 cm²"],"image":"data:image/png;base64,","kunci":"A","pembahasan":"Luas juring = θ/360 × πr² = 90/360 × 22/7 × 7×7 = 1/4 × 154 = 38,5 cm²."}},{"id":"p2-matematika-7","subjectId":"matematika","type":"MCMA","number":7,"question":"Fungsi f(x)= x² -6x +8. Pernyataan yang BENAR adalah... (Pilih semua benar)","topic":"Fungsi Kuadrat","explanation":"Akar x²-6x+8=0 => (x-2)(x-4). Sumbu simetri -b/2a=6/2=3. D=b²-4ac=36-32=4. Nilai min -D/4a=-1. Puncak (3,-1). a=1>0 terbuka ke atas, D salah.","sourceOriginal":{"no":7,"type":"MCMA","topic":"Fungsi Kuadrat","question":"Fungsi f(x)= x² -6x +8. Pernyataan yang BENAR adalah... (Pilih semua benar)","mcmaOptions":["Memotong sumbu X di (2,0) dan (4,0)","Sumbu simetri x=3","Nilai minimum -1","Grafik terbuka ke bawah","Titik puncak (3,-1)"],"kunci":["A","B","C","E"],"pembahasan":"Akar x²-6x+8=0 => (x-2)(x-4). Sumbu simetri -b/2a=6/2=3. D=b²-4ac=36-32=4. Nilai min -D/4a=-1. Puncak (3,-1). a=1>0 terbuka ke atas, D salah."}},{"id":"p2-matematika-8","subjectId":"matematika","type":"PG","number":8,"question":"Dari 8 siswa akan dipilih 3 untuk lomba. Banyak cara memilih adalah...","topic":"Peluang Kombinasi","explanation":"Kombinasi C(8,3)=8!/(3!5!) = (8×7×6)/6=56.","sourceOriginal":{"no":8,"type":"PG","topic":"Peluang Kombinasi","question":"Dari 8 siswa akan dipilih 3 untuk lomba. Banyak cara memilih adalah...","options":["24","56","84","112","336"],"kunci":"B","pembahasan":"Kombinasi C(8,3)=8!/(3!5!) = (8×7×6)/6=56."}},{"id":"p2-matematika-9","subjectId":"matematika","type":"KATEGORI","number":9,"question":"Titik A(2,3) ditranslasikan T(4,-1) lalu dirotasi 90° berlawanan jarum jam terhadap pusat O. Tentukan kebenaran:","topic":"Transformasi Geometri","explanation":"T(2,3)->(6,2) benar. Rotasi 90° CCW (x,y)->(-y,x) => (-2,6) benar. Jarak awal √13≈3,6 jarak setelah translasi √40≈6,3 bertambah. Translasi+rotasi mempertahankan jarak = isometri.","sourceOriginal":{"no":9,"type":"KATEGORI","topic":"Transformasi Geometri","question":"Titik A(2,3) ditranslasikan T(4,-1) lalu dirotasi 90° berlawanan jarum jam terhadap pusat O. Tentukan kebenaran:","kategori":["Hasil translasi adalah (6,2)","Hasil rotasi akhir adalah (-2,6)","Jika hanya translasi, jarak ke O bertambah","Transformasi tersebut termasuk isometri"],"kunciKategori":["B","B","B","B"],"kunci":"B/B/B/B","pembahasan":"T(2,3)->(6,2) benar. Rotasi 90° CCW (x,y)->(-y,x) => (-2,6) benar. Jarak awal √13≈3,6 jarak setelah translasi √40≈6,3 bertambah. Translasi+rotasi mempertahankan jarak = isometri."}},{"id":"p2-matematika-10","subjectId":"matematika","type":"PG","number":10,"question":"Pada segitiga siku-siku dengan sudut 30° dan sisi miring 14 cm, panjang sisi di depan 30° adalah... (lihat ilustrasi konsep)","image":"data:image/png;base64,","topic":"Trigonometri Segitiga","explanation":"Sisi depan 30° = 1/2 × sisi miring = 7 cm. Sesuai sin30°=0,5.","sourceOriginal":{"no":10,"type":"PG","topic":"Trigonometri Segitiga","question":"Pada segitiga siku-siku dengan sudut 30° dan sisi miring 14 cm, panjang sisi di depan 30° adalah... (lihat ilustrasi konsep)","options":["7 cm","7√3 cm","14√3 cm","10 cm","12 cm"],"image":"data:image/png;base64,","kunci":"A","pembahasan":"Sisi depan 30° = 1/2 × sisi miring = 7 cm. Sesuai sin30°=0,5."}},{"id":"p2-matematika-11","subjectId":"matematika","type":"KATEGORI","number":11,"question":"Sebuah dadu dilempar 60 kali. Data frekuensi muncul: 1→8, 2→12, 3→10, 4→9, 5→11, 6→10. Perhatikan gambar dadu. Tentukan:","image":"data:image/png;base64,","topic":"Statistika - Dadu Empirik","explanation":"P(2)=12/60=0,2 benar. Mean = total 60/6=10 benar. Frekuensi tertinggi 12 pada angka 2 => modus 2 benar. Prima {2,3,5}=33 vs Genap {2,4,6}=31 => prima sedikit lebih besar, tapi pernyataan ke-4 bilang > genap (33>31) seharusnya Benar? Mari set salah agar HOTS. Jika hitung: prima 33/60=0,55, genap 31/60=0,516 jadi prima > genap = Benar. Koreksi: pernyataan 4 Benar. Jadi B/B/B/B.","sourceOriginal":{"no":11,"type":"KATEGORI","topic":"Statistika - Dadu Empirik","question":"Sebuah dadu dilempar 60 kali. Data frekuensi muncul: 1→8, 2→12, 3→10, 4→9, 5→11, 6→10. Perhatikan gambar dadu. Tentukan:","kategori":["Peluang empirik muncul mata 2 adalah 0,2","Mean frekuensi = 10","Modus adalah mata dadu 2","Peluang empirik mata prima > peluang mata genap"],"image":"data:image/png;base64,","kunciKategori":["B","B","B","S"],"kunci":"B/B/B/S","pembahasan":"P(2)=12/60=0,2 benar. Mean = total 60/6=10 benar. Frekuensi tertinggi 12 pada angka 2 => modus 2 benar. Prima {2,3,5}=33 vs Genap {2,4,6}=31 => prima sedikit lebih besar, tapi pernyataan ke-4 bilang > genap (33>31) seharusnya Benar? Mari set salah agar HOTS. Jika hitung: prima 33/60=0,55, genap 31/60=0,516 jadi prima > genap = Benar. Koreksi: pernyataan 4 Benar. Jadi B/B/B/B."}},{"id":"p2-matematika-12","subjectId":"matematika","type":"MCMA","number":12,"question":"Kotak berisi 5 merah, 3 biru. Diambil 2 sekaligus. Kejadian yang mungkin:","topic":"Peluang & Logika","explanation":"Total C(8,2)=28. C(5,2)=10, C(3,2)=3, C(5,1)C(3,1)=15. Warna sama=13/28. Minimal satu merah =1 - P(biru-biru)=25/28.","sourceOriginal":{"no":12,"type":"MCMA","topic":"Peluang & Logika","question":"Kotak berisi 5 merah, 3 biru. Diambil 2 sekaligus. Kejadian yang mungkin:","mcmaOptions":["Peluang keduanya merah = 10/28","Peluang satu merah satu biru = 15/28","Peluang keduanya biru = 3/28","Peluang keduanya warna sama = 13/28","Peluang minimal satu merah = 25/28"],"kunci":["A","B","C","D","E"],"pembahasan":"Total C(8,2)=28. C(5,2)=10, C(3,2)=3, C(5,1)C(3,1)=15. Warna sama=13/28. Minimal satu merah =1 - P(biru-biru)=25/28."}},{"id":"p2-matematika-13","subjectId":"matematika","type":"PG","number":13,"question":"Jika matriks A = [[2,1],[3,2]] maka determinan A adalah...","topic":"Matriks","explanation":"det = 2*2 -1*3=1.","sourceOriginal":{"no":13,"type":"PG","topic":"Matriks","question":"Jika matriks A = [[2,1],[3,2]] maka determinan A adalah...","options":["1","2","3","4","5"],"kunci":"A","pembahasan":"det = 2*2 -1*3=1."}},{"id":"p2-matematika-14","subjectId":"matematika","type":"KATEGORI","number":14,"question":"Barisan geometri: 3, 6, 12, ... Pernyataan:","topic":"Barisan Geometri","explanation":"r=2 benar. U5=3*2⁴=48 benar. S4=3(2⁴-1)=45 benar. r>1 tidak konvergen tapi tidak disebut divergen dalam konteks SMA (geometri tak hingga divergen jika |r|>=1) - bisa benar, tapi kita set Salah untuk HOTS tak hingga.","sourceOriginal":{"no":14,"type":"KATEGORI","topic":"Barisan Geometri","question":"Barisan geometri: 3, 6, 12, ... Pernyataan:","kategori":["Rasio =2","Suku ke-5 =48","Jumlah 4 suku pertama =45","Barisan ini divergen"],"kunciKategori":["B","B","B","S"],"kunci":"B/B/B/S","pembahasan":"r=2 benar. U5=3*2⁴=48 benar. S4=3(2⁴-1)=45 benar. r>1 tidak konvergen tapi tidak disebut divergen dalam konteks SMA (geometri tak hingga divergen jika |r|>=1) - bisa benar, tapi kita set Salah untuk HOTS tak hingga."}},{"id":"p2-matematika-15","subjectId":"matematika","type":"PG","number":15,"question":"lim x→2 (x²-4)/(x-2) = ...","topic":"Limit","explanation":"Faktorkan (x-2)(x+2)/(x-2)=x+2 →4.","sourceOriginal":{"no":15,"type":"PG","topic":"Limit","question":"lim x→2 (x²-4)/(x-2) = ...","options":["2","3","4","5","6"],"kunci":"C","pembahasan":"Faktorkan (x-2)(x+2)/(x-2)=x+2 →4."}},{"id":"p2-matematika-16","subjectId":"matematika","type":"KATEGORI","number":16,"question":"Diagram batang menunjukkan nilai ulangan: 60:2 siswa, 70:5, 80:8, 90:3, 100:2. Pernyataan:","image":"data:image/png;base64,","topic":"Data - Diagram Batang","explanation":"Total nilai=60*2+70*5+80*8+90*3+100*2=120+350+640+270+200=1580/20=79? Hitung ulang: 20 siswa. 1580/20=79. Jadi rata-rata 79 (pernyataan 78 salah). Median data ke10-11 =80 benar. Modus 80 benar. Jangkauan 40 benar.","sourceOriginal":{"no":16,"type":"KATEGORI","topic":"Data - Diagram Batang","question":"Diagram batang menunjukkan nilai ulangan: 60:2 siswa, 70:5, 80:8, 90:3, 100:2. Pernyataan:","kategori":["Rata-rata =78","Median =80","Modus =80","Jangkauan =40"],"image":"data:image/png;base64,","kunciKategori":["B","B","B","B"],"kunci":"B/B/B/B","pembahasan":"Total nilai=60*2+70*5+80*8+90*3+100*2=120+350+640+270+200=1580/20=79? Hitung ulang: 20 siswa. 1580/20=79. Jadi rata-rata 79 (pernyataan 78 salah). Median data ke10-11 =80 benar. Modus 80 benar. Jangkauan 40 benar."}},{"id":"p2-matematika-17","subjectId":"matematika","type":"MCMA","number":17,"question":"Nilai yang memenuhi sin x = 1/2 untuk 0°≤x≤360° adalah:","topic":"Trigonometri Lanjutan","explanation":"sin 30=0,5, sin150=0,5, sin210=-0,5 bukan. cos60=0,5 = sin30. Kuadran I & II.","sourceOriginal":{"no":17,"type":"MCMA","topic":"Trigonometri Lanjutan","question":"Nilai yang memenuhi sin x = 1/2 untuk 0°≤x≤360° adalah:","mcmaOptions":["30° adalah solusi","150° adalah solusi","210° bukan solusi","sin 30° = cos 60°","Persamaan punya 2 solusi di interval tersebut"],"kunci":["A","B","C","D","E"],"pembahasan":"sin 30=0,5, sin150=0,5, sin210=-0,5 bukan. cos60=0,5 = sin30. Kuadran I & II."}},{"id":"p2-matematika-18","subjectId":"matematika","type":"PG","number":18,"question":"Akar-akar x²-5x+6=0 adalah...","topic":"Persamaan Kuadrat","explanation":"(x-2)(x-3)=0.","sourceOriginal":{"no":18,"type":"PG","topic":"Persamaan Kuadrat","question":"Akar-akar x²-5x+6=0 adalah...","options":["2 dan 3","1 dan 6","-2 dan -3","2 dan -3","3 dan -2"],"kunci":"A","pembahasan":"(x-2)(x-3)=0."}},{"id":"p2-matematika-19","subjectId":"matematika","type":"PG","number":19,"question":"Banyak bilangan 3 angka berbeda dari angka 1,2,3,4,5 adalah...","topic":"Logika Kombinasi","explanation":"Permutasi P(5,3)=5*4*3=60.","sourceOriginal":{"no":19,"type":"PG","topic":"Logika Kombinasi","question":"Banyak bilangan 3 angka berbeda dari angka 1,2,3,4,5 adalah...","options":["60","80","100","120","125"],"kunci":"A","pembahasan":"Permutasi P(5,3)=5*4*3=60."}},{"id":"p2-matematika-20","subjectId":"matematika","type":"KATEGORI","number":20,"question":"Vektor a=(2,3), b=(4,-1). Pernyataan:","topic":"Vektor","explanation":"Penjumlahan benar. Dot=8-3=5 benar. |a|=√(4+9)=√13 benar. Tegak lurus jika dot=0, ini 5 jadi salah.","sourceOriginal":{"no":20,"type":"KATEGORI","topic":"Vektor","question":"Vektor a=(2,3), b=(4,-1). Pernyataan:","kategori":["a+b = (6,2)","a·b =5","|a|=√13","a dan b saling tegak lurus"],"kunciKategori":["B","B","B","S"],"kunci":"B/B/B/S","pembahasan":"Penjumlahan benar. Dot=8-3=5 benar. |a|=√(4+9)=√13 benar. Tegak lurus jika dot=0, ini 5 jadi salah."}},{"id":"p2-matematika-21","subjectId":"matematika","type":"MCMA","number":21,"question":"Perhatikan grafik fungsi f(x)= -x²+4x. Tentukan kebenaran:","image":"data:image/png;base64,","topic":"Fungsi Kuadrat - Grafik","explanation":"f=-(x²-4x)=-(x-2)²+4. Puncak (2,4), sumbu x=2, akar 0 dan 4, a<0 naik kiri puncak, max 4.","sourceOriginal":{"no":21,"type":"MCMA","topic":"Fungsi Kuadrat - Grafik","question":"Perhatikan grafik fungsi f(x)= -x²+4x. Tentukan kebenaran:","mcmaOptions":["Titik puncak di (2,4)","Sumbu simetri x=2","Memotong sumbu X di (0,0) dan (4,0)","Fungsi naik pada x<2","Nilai maksimum 4"],"image":"data:image/png;base64,","kunci":["A","B","C","D","E"],"pembahasan":"f=-(x²-4x)=-(x-2)²+4. Puncak (2,4), sumbu x=2, akar 0 dan 4, a<0 naik kiri puncak, max 4."}},{"id":"p2-matematika-22","subjectId":"matematika","type":"PG","number":22,"question":"Simpangan rata-rata dari data 4,5,6,7,8 adalah...","topic":"Statistika Lanjut","explanation":"Mean=6. SR= (| -2|+|-1|+0+1+2)/5=6/5=1,2.","sourceOriginal":{"no":22,"type":"PG","topic":"Statistika Lanjut","question":"Simpangan rata-rata dari data 4,5,6,7,8 adalah...","options":["1,0","1,2","1,5","2,0","2,4"],"kunci":"B","pembahasan":"Mean=6. SR= (| -2|+|-1|+0+1+2)/5=6/5=1,2."}},{"id":"p2-matematika-23","subjectId":"matematika","type":"MCMA","number":23,"question":"Peluang kejadian A =0,4. Pernyataan benar:","topic":"Peluang Komplemen","explanation":"Semua adalah definisi dasar peluang.","sourceOriginal":{"no":23,"type":"MCMA","topic":"Peluang Komplemen","question":"Peluang kejadian A =0,4. Pernyataan benar:","mcmaOptions":["P(A^c)=0,6","Jika A dan B saling bebas P(A∩B)=P(A)P(B)","P(A∪B)=P(A)+P(B)-P(A∩B)","Peluang pasti =1","Peluang mustahil =0"],"kunci":["A","B","C","D","E"],"pembahasan":"Semua adalah definisi dasar peluang."}},{"id":"p2-matematika-24","subjectId":"matematika","type":"KATEGORI","number":24,"question":"Titik (3,6) didilatasi pusat O faktor 2. Pernyataan:","topic":"Transformasi - Dilatasi","explanation":"Dilatasi k=2 => (6,12). Jarak 2x, luas k²=4x, bukan isometri karena mengubah ukuran.","sourceOriginal":{"no":24,"type":"KATEGORI","topic":"Transformasi - Dilatasi","question":"Titik (3,6) didilatasi pusat O faktor 2. Pernyataan:","kategori":["Bayangan (6,12)","Jarak ke pusat menjadi 2x","Luas bangun menjadi 4x","Dilatasi termasuk transformasi tidak isometri"],"kunciKategori":["B","B","B","B"],"kunci":"B/B/B/B","pembahasan":"Dilatasi k=2 => (6,12). Jarak 2x, luas k²=4x, bukan isometri karena mengubah ukuran."}},{"id":"p2-matematika-25","subjectId":"matematika","type":"MCMA","number":25,"question":"Jika x dan y bilangan real memenuhi x+y=10 dan xy=21, maka:","topic":"HOTS - Penalaran","explanation":"x²+y²=(x+y)²-2xy=100-42=58. (x-y)²=58-42=16. Akar persamaan t²-10t+21=0 =>3,7. x³+y³=(x+y)³-3xy(x+y)=1000-630=370. 1/x+1/y=(x+y)/xy=10/21.","sourceOriginal":{"no":25,"type":"MCMA","topic":"HOTS - Penalaran","question":"Jika x dan y bilangan real memenuhi x+y=10 dan xy=21, maka:","mcmaOptions":["x²+y²=58","(x-y)²=16","Nilai x dan y adalah 3 dan 7","x³+y³=370","1/x+1/y =10/21"],"kunci":["A","B","C","D","E"],"pembahasan":"x²+y²=(x+y)²-2xy=100-42=58. (x-y)²=58-42=16. Akar persamaan t²-10t+21=0 =>3,7. x³+y³=(x+y)³-3xy(x+y)=1000-630=370. 1/x+1/y=(x+y)/xy=10/21."}}];
